insert into `ref_couverture_aaa` (`code`, `libelle`, `description`, `ordre`, `debut_validite`, `fin_validite`, `note`) values ('a_determiner', 'À déterminer', 'Qualification non tranchée. Le trajet domicile-travail, la pause repas prise hors de l''entreprise et le déplacement entre deux sites relèvent du Code de la sécurité sociale, qui ne figure pas au corpus documentaire du projet. Tant que la source manque, l''état reste celui-ci — un trou déclaré vaut mieux qu''une qualification inventée.', 3, '1970-01-01', '2037-12-31', null);
