insert into `parametres_legaux` (`id`, `famille`, `cle_parametre`, `libelle`, `valeur_num`, `valeur_texte`, `valeur_json`, `unite`, `debut_validite`, `fin_validite`, `indice_reference`, `source`, `reference_legale`, `note`, `derive_de_cle`, `facteur_derive`, `tolerance_derivation`) values ('27933c51-bca0-4ef4-ba6a-14c6d8c6c6ff', 'conges', 'Enfant_Jours_18', 'Congé pour raisons familiales — enfant de 13 à 18 ans accomplis et hospitalisé', 5, null, null, 'jours', '1970-01-01', '2037-12-31', null, 'Legilux', 'art. L.234-52', 'L''hospitalisation est une condition, pas une circonstance : sans elle, le droit ne s''ouvre pas pour cette tranche.', null, null, 0.02);
insert into `parametres_legaux` (`id`, `famille`, `cle_parametre`, `libelle`, `valeur_num`, `valeur_texte`, `valeur_json`, `unite`, `debut_validite`, `fin_validite`, `indice_reference`, `source`, `reference_legale`, `note`, `derive_de_cle`, `facteur_derive`, `tolerance_derivation`) values ('1aa75140-bf0d-44d3-8faf-abc275062103', 'conges', 'Enfant_Handicape', 'Congé pour raisons familiales — levée de la limite d''âge, enfant bénéficiaire de l''allocation spéciale supplémentaire', 1, null, null, 'booléen', '1970-01-01', '2037-12-31', null, 'Legilux', 'art. L.234-51', 'Drapeau, et non un nombre de jours : la limite d''âge de dix-huit ans ne s''applique pas. Voir l''art. 274 du Code de la sécurité sociale pour l''allocation spéciale supplémentaire.', null, null, 0.02);
insert into `parametres_legaux` (`id`, `famille`, `cle_parametre`, `libelle`, `valeur_num`, `valeur_texte`, `valeur_json`, `unite`, `debut_validite`, `fin_validite`, `indice_reference`, `source`, `reference_legale`, `note`, `derive_de_cle`, `facteur_derive`, `tolerance_derivation`) values ('ac21b1b4-6cb3-44ab-ae49-cff377b8d4d3', 'conges', 'Adulte_Handicap', 'Congé supplémentaire du salarié handicapé ou reclassé', 6, null, null, 'jours ouvrables', '1970-01-01', '2037-12-31', null, 'Spécification transmise le 17 septembre 2026', null, 'Référence légale à établir. Le seul congé supplémentaire de six jours ouvrables attesté par le Code du travail au corpus est celui de l''art. L.231-11, accordé lorsque le repos hebdomadaire de quarante-quatre heures n''est pas respecté : c''est un autre droit, et la confusion serait coûteuse.', null, null, 0.02);
